-- Les questions du site passent en base, dans quizz_questions, avec celles des joueurs : une seule source pour les
-- parties, les duels, les statistiques et les corrections (une question contestée se corrige depuis l'administration).
-- Avant, elles étaient écrites dans le code (src/Components/Quizz/topics).
--
-- number : numéro fixe d'une question du site dans son thème (1 à 999 : écrites à la main ; 1001 et plus : tirées
--          de Wikidata) ; vide pour une question d'un joueur. Une question du site n'a pas d'auteur (author_id vide).
-- Les statistiques désignaient une question du site par site:<thème>:<numéro> : elle devient q:<id>, comme les
-- questions des joueurs (quizz_answers, et les questions gardées dans quizz_games et quizz_duels).
alter table quizz_questions
    add column number integer;

create unique index quizz_questions_number_idx on quizz_questions (topic_id, number) where number is not null;

