-- Clés des statistiques déjà enregistrées : site:<thème>:<numéro> → q:<id>
update quizz_answers a
set question_key = 'q:' || q.id
from quizz_questions q
where q.number is not null
  and a.question_key = 'site:' || q.topic_id || ':' || q.number;

update quizz_games g
set questions = (select jsonb_agg(case when q.id is null then e else jsonb_set(e, '{key}', to_jsonb('q:' || q.id)) end
                                  order by i)
                 from jsonb_array_elements(g.questions) with ordinality as x (e, i)
                          left join quizz_questions q on q.number is not null and e ->> 'key' = 'site:' || q.topic_id || ':' || q.number)
where g.questions::text like '%"site:%';

update quizz_duels d
set questions = (select jsonb_agg(case when q.id is null then e else jsonb_set(e, '{key}', to_jsonb('q:' || q.id)) end
                                  order by i)
                 from jsonb_array_elements(d.questions) with ordinality as x (e, i)
                          left join quizz_questions q on q.number is not null and e ->> 'key' = 'site:' || q.topic_id || ':' || q.number)
where d.questions::text like '%"site:%';
